@startuml

class Researcher {
  + name : string
  + surname : string
  + isAvailable : boolean
}

class SeniorResearcher extends Researcher {}

class JuniorResearcher extends Researcher {}

class Team {
  + name : string
}

class Project {
  + name : string
}

class Area {
  + name : string
}

class AreaManager {
  + name : string
}

Area "1" -- "1" AreaManager : has
Area "1" -- "1..*" Team : groups
Team "1" -- "1" SeniorResearcher : is led by
Team "1" *-- "1..*" JuniorResearcher : includes
Team "1" -- "1" Project : carries out

@enduml

